// ===================================================================
// หน้า My Booking: แสดงรายการจองของผู้ใช้ พร้อมปุ่มเช็กอินและยกเลิกการจอง
// ===================================================================

import { useCallback, useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import "../css/homepage.css";
import "../css/Mybooking.css";
import Navbar from "../components/navbar";

// ---------- ค่าคงที่ ----------

// URL ของ Backend API
const API_BASE_URL = "http://localhost:5001";

// พิกัดสถานที่สำหรับเช็กอิน (ละติจูด / ลองจิจูด)
const CHECKIN_LOCATION = {
  latitude: 14.0735763,
  longitude: 100.606303,
};

// ระยะสูงสุดที่อนุญาตให้เช็กอินได้ (หน่วยเป็นเมตร)
const CHECKIN_RADIUS_METERS = 2000;

// ---------- ฟังก์ชันช่วยเหลือ (Helpers) ----------

// อ่านข้อมูลผู้ใช้ที่เก็บไว้ใน localStorage (ถ้า parse ไม่ได้จะคืนค่า null)
function getStoredUser() {
  try {
    return JSON.parse(localStorage.getItem("user") || "null");
  } catch (error) {
    console.error("Unable to read user data:", error);
    return null;
  }
}

// ดึง id ของผู้ใช้ รองรับหลายชื่อฟิลด์จาก Backend
function getUserId(user) {
  return user?.id ?? user?.user_id ?? user?.userId ?? null;
}

// ดึง id ของการจอง รองรับหลายชื่อฟิลด์
function getBookingId(booking) {
  return booking?.id ?? booking?.booking_id ?? null;
}

// ตรวจสอบว่าการจองนี้เช็กอินไปแล้วหรือยัง (เช็กจากหลายรูปแบบของข้อมูล)
function isAlreadyCheckedIn(booking) {
  return Boolean(
    booking?.checked_in_at ||
      booking?.checkedInAt ||
      booking?.checkin_status === "checked_in" ||
      booking?.check_in_status === "checked_in" ||
      booking?.checked_in === true ||
      booking?.checked_in === 1
  );
}

// คำนวณระยะทางระหว่างสองพิกัดด้วยสูตร Haversine (ผลลัพธ์เป็นเมตร)
function getDistanceInMeters(lat1, lon1, lat2, lon2) {
  const toRadians = (degrees) => (degrees * Math.PI) / 180;
  const earthRadius = 6371000; // รัศมีโลก (เมตร)

  const dLat = toRadians(lat2 - lat1);
  const dLon = toRadians(lon2 - lon1);

  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRadians(lat1)) *
      Math.cos(toRadians(lat2)) *
      Math.sin(dLon / 2) ** 2;

  return earthRadius * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

// จัดรูปแบบวันที่ เช่น "20 Oct 2026"
function formatDate(dateValue) {
  if (!dateValue) return "-";

  const value = String(dateValue);

  // ถ้าเป็นรูปแบบ YYYY-MM-DD ให้เติมเวลาเพื่อกันปัญหา timezone
  const date = /^\d{4}-\d{2}-\d{2}$/.test(value)
    ? new Date(`${value}T00:00:00`)
    : new Date(value);

  // ถ้าแปลงเป็นวันที่ไม่ได้ ให้แสดงค่าเดิม
  if (Number.isNaN(date.getTime())) return value;

  return date.toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
}

// จัดรูปแบบเวลาเป็น HH:mm
function formatTime(timeValue) {
  if (!timeValue) return "-";

  const value = String(timeValue);

  // กรณีเป็นรูปแบบ "HH:mm" หรือ "HH:mm:ss"
  const match = value.match(/^(\d{1,2}):(\d{2})/);

  if (match) {
    return `${match[1].padStart(2, "0")}:${match[2]}`;
  }

  // กรณีเป็นวันที่-เวลาเต็ม (เช่น ISO string)
  const date = new Date(value);

  if (!Number.isNaN(date.getTime())) {
    return date.toLocaleTimeString("en-GB", {
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
    });
  }

  return value;
}

// แปลงสถานะจาก Backend เป็นข้อความที่แสดง (label) และกลุ่มสี (className)
function getStatus(status) {
  const value = String(status || "pending").toLowerCase();

  // กลุ่มยกเลิก / ไม่สำเร็จ
  if (["cancelled", "canceled", "rejected", "expired"].includes(value)) {
    return {
      label:
        value === "canceled"
          ? "Cancelled"
          : value.charAt(0).toUpperCase() + value.slice(1),
      className: "cancelled",
    };
  }

  // กลุ่มยืนยันแล้ว
  if (["confirmed", "approved", "success"].includes(value)) {
    return {
      label:
        value === "success"
          ? "Confirmed"
          : value.charAt(0).toUpperCase() + value.slice(1),
      className: "confirmed",
    };
  }

  // กลุ่มเสร็จสิ้น
  if (["completed", "finished"].includes(value)) {
    return {
      label: "Completed",
      className: "completed",
    };
  }

  // สถานะอื่นๆ ถือเป็นรอดำเนินการ
  return {
    label: value.charAt(0).toUpperCase() + value.slice(1),
    className: "pending",
  };
}

// ---------- Component หลัก ----------

function Mybooking() {
  const navigate = useNavigate();

  // ผู้ใช้ปัจจุบัน (อ่านจาก localStorage ครั้งเดียวตอนเริ่ม)
  const [user] = useState(() => getStoredUser());

  // รายการจองทั้งหมดของผู้ใช้
  const [bookings, setBookings] = useState([]);

  // สถานะการโหลดและข้อความแจ้งเตือน
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");

  // id ของการจองที่กำลังยกเลิก / กำลังเช็กอิน (ใช้ปิดปุ่มระหว่างรอ)
  const [cancellingId, setCancellingId] = useState(null);
  const [checkingInId, setCheckingInId] = useState(null);

  // รายการ id ที่เช็กอินแล้ว (เก็บเป็น string)
  const [checkedInIds, setCheckedInIds] = useState([]);

  const userId = getUserId(user);

  // ถ้าไม่มีข้อมูลผู้ใช้ ให้กลับไปหน้าล็อกอิน
  useEffect(() => {
    if (!user || userId == null || userId === "") {
      navigate("/", { replace: true });
    }
  }, [user, userId, navigate]);

  // ดึงรายการจองของผู้ใช้จาก API
  const fetchBookings = useCallback(async () => {
    if (userId == null || userId === "") {
      setLoading(false);
      setError("กรุณาเข้าสู่ระบบใหม่");
      return;
    }

    setLoading(true);
    setError("");

    try {
      const token = localStorage.getItem("token");

      const response = await fetch(
        `${API_BASE_URL}/api/bookings/${encodeURIComponent(userId)}`,
        {
          method: "GET",
          headers: {
            Accept: "application/json",
            "X-User-Id": String(userId),
            // แนบ token เฉพาะเมื่อมี
            ...(token ? { Authorization: `Bearer ${token}` } : {}),
          },
        }
      );

      // ถ้า response ไม่ใช่ JSON ให้ใช้ object ว่างแทน
      const data = await response.json().catch(() => ({}));

      if (!response.ok || data.success === false) {
        // 401/403 = หมดสิทธิ์หรือ token หมดอายุ
        if (response.status === 401 || response.status === 403) {
          throw new Error("กรุณาเข้าสู่ระบบใหม่");
        }

        throw new Error(data.message || "Unable to load your bookings.");
      }

      // รองรับทั้งกรณีที่ API คืน array ตรงๆ หรือคืนเป็น { bookings: [...] }
      const bookingList = Array.isArray(data)
        ? data
        : Array.isArray(data.bookings)
          ? data.bookings
          : [];

      setBookings(bookingList);

      // รวม id ที่เช็กอินแล้วจากเซิร์ฟเวอร์ เข้ากับที่มีอยู่ (ใช้ Set กันซ้ำ)
      setCheckedInIds((previousIds) => [
        ...new Set([
          ...previousIds,
          ...bookingList
            .filter(isAlreadyCheckedIn)
            .map(getBookingId)
            .filter((id) => id != null)
            .map(String),
        ]),
      ]);
    } catch (err) {
      console.error("Failed to fetch bookings:", err);
      setError(err.message || "Something went wrong while loading your bookings.");
    } finally {
      setLoading(false);
    }
  }, [userId]);

  // โหลดรายการจองเมื่อเข้าหน้านี้
  useEffect(() => {
    if (userId != null && userId !== "") {
      fetchBookings();
    }
  }, [userId, fetchBookings]);

  // ---------- เช็กอิน ----------
  const handleCheckIn = (booking) => {
    const bookingId = getBookingId(booking);

    if (bookingId == null) {
      setError("Unable to identify this booking.");
      return;
    }

    // ป้องกันการเช็กอินซ้ำ
    const checkedIn =
      isAlreadyCheckedIn(booking) ||
      checkedInIds.includes(String(bookingId));

    if (checkedIn) {
      setNotice("You have already checked in for this booking.");
      return;
    }

    // การจองที่ยกเลิก / เสร็จสิ้นแล้วไม่สามารถเช็กอินได้
    const status = getStatus(booking.status);
    const rawStatus = String(booking.status || "").toLowerCase();

    if (
      ["cancelled", "completed"].includes(status.className) ||
      ["canceled", "rejected", "expired"].includes(rawStatus)
    ) {
      setError("This booking is not eligible for check-in.");
      return;
    }

    // ตรวจสอบว่าเบราว์เซอร์รองรับการขอตำแหน่ง
    if (!navigator.geolocation) {
      setError("Your browser does not support location services.");
      return;
    }

    // Geolocation ใช้ได้เฉพาะ HTTPS หรือ localhost
    if (!window.isSecureContext) {
      setError("Location access requires HTTPS or localhost. Please open the app securely.");
      return;
    }

    setCheckingInId(bookingId);
    setError("");
    setNotice("");

    // ขอตำแหน่งปัจจุบันของผู้ใช้
    navigator.geolocation.getCurrentPosition(
      // กรณีได้รับตำแหน่งสำเร็จ
      async (position) => {
        try {
          const { latitude, longitude, accuracy } = position.coords;

          // คำนวณระยะห่างจากจุดเช็กอิน
          const distance = getDistanceInMeters(
            latitude,
            longitude,
            CHECKIN_LOCATION.latitude,
            CHECKIN_LOCATION.longitude
          );

          // อยู่ไกลเกินกำหนด ไม่อนุญาตให้เช็กอิน
          if (distance > CHECKIN_RADIUS_METERS) {
            setError(
              `You are approximately ${Math.round(distance)} meters away. Please move within 2000 meters of the check-in location.`
            );
            return;
          }

          const token = localStorage.getItem("token");

          // ส่งคำขอเช็กอินไปที่ Backend
          const response = await fetch(
            `${API_BASE_URL}/api/bookings/${encodeURIComponent(bookingId)}/check-in`,
            {
              method: "POST",
              headers: {
                Accept: "application/json",
                "Content-Type": "application/json",
                "X-User-Id": String(userId),
                ...(token ? { Authorization: `Bearer ${token}` } : {}),
              },
              body: JSON.stringify({
                user_id: userId,
                latitude,
                longitude,
                accuracy,
              }),
            }
          );

          const data = await response.json().catch(() => ({}));

          if (!response.ok || data.success === false) {
            throw new Error(data.message || "Unable to complete check-in.");
          }

          // บันทึกว่าเช็กอินแล้ว เพื่อให้ปุ่มเปลี่ยนสถานะทันที
          setCheckedInIds((ids) => [
            ...new Set([...ids, String(bookingId)]),
          ]);

          setNotice(
            data.message ||
              `Check-in successful! You are approximately ${Math.round(distance)} meters from the check-in location.`
          );

          // โหลดรายการจองใหม่เพื่อให้ข้อมูลตรงกับเซิร์ฟเวอร์
          await fetchBookings();
        } catch (err) {
          console.error("Check-in failed:", err);
          setError(err.message || "Unable to complete check-in.");
        } finally {
          setCheckingInId(null);
        }
      },
      // กรณีขอตำแหน่งไม่สำเร็จ แปลง error code เป็นข้อความ
      (err) => {
        setCheckingInId(null);

        const message =
          err.code === 1
            ? "Location permission denied. Please allow location access."
            : err.code === 2
              ? "Unable to determine your location. Please try again."
              : err.code === 3
                ? "Location request timed out. Please try again."
                : "Unable to access your location.";

        setError(message);
      },
      // ตัวเลือกการขอตำแหน่ง
      {
        enableHighAccuracy: true, // ขอความแม่นยำสูง
        timeout: 15000,           // รอสูงสุด 15 วินาที
        maximumAge: 0,            // ไม่ใช้ตำแหน่งที่แคชไว้
      }
    );
  };

  // ---------- ยกเลิกการจอง ----------
  const handleCancel = async (booking) => {
    const bookingId = getBookingId(booking);

    if (bookingId == null) {
      setError("Unable to identify this booking.");
      return;
    }

    const status = getStatus(booking.status);

    // ถ้ายกเลิกหรือเสร็จสิ้นไปแล้ว ไม่ต้องทำอะไร
    if (["cancelled", "completed"].includes(status.className)) {
      return;
    }

    // ถามยืนยันก่อนยกเลิก
    if (!window.confirm("Are you sure you want to cancel this booking?")) {
      return;
    }

    setCancellingId(bookingId);
    setError("");
    setNotice("");

    try {
      const token = localStorage.getItem("token");

      // ส่งคำขอลบการจองไปที่ Backend
      const response = await fetch(
        `${API_BASE_URL}/api/bookings/${encodeURIComponent(bookingId)}`,
        {
          method: "DELETE",
          headers: {
            Accept: "application/json",
            "Content-Type": "application/json",
            "X-User-Id": String(userId),
            ...(token ? { Authorization: `Bearer ${token}` } : {}),
          },
        }
      );

      const data = await response.json().catch(() => ({}));

      if (!response.ok || data.success === false) {
        throw new Error(data.message || "Unable to cancel this booking.");
      }

      setNotice(data.message || "Booking cancelled successfully.");

      // โหลดรายการใหม่หลังยกเลิกสำเร็จ
      await fetchBookings();
    } catch (err) {
      console.error("Failed to cancel booking:", err);
      setError(err.message || "Something went wrong while cancelling.");
    } finally {
      setCancellingId(null);
    }
  };

  // ---------- ส่วนแสดงผล (UI) ----------
  return (
    <div className="homepage mybooking-page">
      {/* แถบเมนูด้านบน */}
      <Navbar />

      <main className="mybooking-main">
        {/* ส่วนหัวของหน้า (Hero) */}
        <section className="mybooking-hero">
          <div className="mybooking-hero-content">
            <p className="mybooking-eyebrow">YOUR SPACE, YOUR TIME</p>
            <h1>My Booking</h1>
            <p>
              Manage your reservations and keep track of your upcoming room
              bookings.
            </p>
          </div>

          {/* วงกลมตกแต่ง */}
          <div className="mybooking-hero-decoration" aria-hidden="true">
            <span className="decoration-circle circle-one" />
            <span className="decoration-circle circle-two" />
            <span className="decoration-circle circle-three" />
          </div>
        </section>

        {/* ส่วนรายการจอง */}
        <section className="booking-section">
          <div className="booking-section-heading">
            <div>
              <p className="section-eyebrow">OVERVIEW</p>
              <h2>Your Reservations</h2>
              <p className="section-description">
                View the details and status of your bookings.
              </p>
            </div>

            {/* ปุ่มรีเฟรชรายการ */}
            <button
              type="button"
              className="refresh-button"
              onClick={() => {
                setNotice("");
                fetchBookings();
              }}
              disabled={loading}
            >
              <span aria-hidden="true">↻</span>
              Refresh
            </button>
          </div>

          {/* สรุปจำนวนการจองทั้งหมด (แสดงเมื่อโหลดเสร็จและไม่มี error) */}
          {!loading && !error && (
            <div className="booking-summary">
              <div className="summary-icon" aria-hidden="true">▣</div>
              <div>
                <span className="summary-label">Total reservations</span>
                <strong>{bookings.length}</strong>
              </div>
            </div>
          )}

          {/* ข้อความแจ้งสำเร็จ */}
          {notice && (
            <div className="booking-alert success-alert" role="status">
              <span aria-hidden="true">✓</span>
              <span>{notice}</span>
              <button type="button" aria-label="Dismiss message" onClick={() => setNotice("")}>
                ×
              </button>
            </div>
          )}

          {/* ข้อความแจ้งข้อผิดพลาด */}
          {error && (
            <div className="booking-alert error-alert" role="alert">
              <span aria-hidden="true">!</span>
              <span>{error}</span>
              <button type="button" className="alert-retry" onClick={fetchBookings} disabled={loading}>
                Try again
              </button>
            </div>
          )}

          {/* เลือกแสดงผลตามสถานะ: กำลังโหลด / โหลดไม่สำเร็จ / ไม่มีรายการ / มีรายการ */}
          {loading ? (
            // กำลังโหลด
            <div className="booking-state">
              <span className="booking-spinner" />
              <h3>Loading your bookings...</h3>
              <p>Please wait while we retrieve your reservations.</p>
            </div>
          ) : error && bookings.length === 0 ? (
            // โหลดไม่สำเร็จและไม่มีข้อมูลเดิมให้แสดง
            <div className="booking-state">
              <div className="state-icon error-state-icon">!</div>
              <h3>Unable to load bookings</h3>
              <p>Please check your connection and try again.</p>
              <button type="button" className="primary-button" onClick={fetchBookings}>
                Try again
              </button>
            </div>
          ) : bookings.length === 0 ? (
            // ยังไม่มีการจอง
            <div className="booking-state empty-booking-state">
              <div className="state-icon" aria-hidden="true">▢</div>
              <h3>No bookings yet</h3>
              <p>
                You haven't made any reservations. Find a room and make your
                first booking.
              </p>
              <button type="button" className="primary-button" onClick={() => navigate("/homepage")}>
                Explore rooms <span aria-hidden="true">→</span>
              </button>
            </div>
          ) : (
            // แสดงรายการจอง
            <div className="booking-list">
              {bookings.map((booking, index) => {
                // เตรียมข้อมูลของแต่ละการ์ด (รองรับหลายชื่อฟิลด์จาก API)
                const bookingId = getBookingId(booking) ?? index;
                const roomName = booking.room_name || booking.room || booking.roomName || "Room";
                const bookingDate = booking.booking_date || booking.date || booking.bookingDate;
                const status = getStatus(booking.status);

                // แสดงปุ่มเช็กอิน/ยกเลิก เฉพาะการจองที่ยังไม่ยกเลิกหรือเสร็จสิ้น
                const canCancel = !["cancelled", "completed"].includes(status.className);

                // เช็กอินแล้วหรือยัง (จากข้อมูลเซิร์ฟเวอร์ หรือจาก state ในหน้านี้)
                const checkedIn =
                  isAlreadyCheckedIn(booking) ||
                  checkedInIds.includes(String(bookingId));

                // สถานะที่ไม่อนุญาตให้เช็กอิน
                const isIneligible = [
                  "cancelled",
                  "canceled",
                  "completed",
                  "expired",
                  "rejected",
                ].includes(String(booking.status || "").toLowerCase());

                return (
                  <article className="booking-card" key={bookingId}>
                    <div className="booking-card-accent" />

                    <div className="booking-card-main">
                      {/* ส่วนบนของการ์ด: ชื่อห้องและสถานะ */}
                      <div className="booking-card-top">
                        <div className="room-heading">
                          <div className="room-icon" aria-hidden="true">
                            <svg
                              viewBox="0 0 24 24"
                              fill="none"
                              stroke="currentColor"
                              strokeWidth="1.7"
                              strokeLinecap="round"
                              strokeLinejoin="round"
                            >
                              <path d="M3 21V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2v16" />
                              <path d="M3 14h18M7 14V9h4v5m2 0V9h4v5M2 21h20" />
                            </svg>
                          </div>
                          <div>
                            <p className="room-label">RESERVED ROOM</p>
                            <h3>{roomName}</h3>
                          </div>
                        </div>

                        {/* ป้ายสถานะการจอง */}
                        <span className={`booking-status status-${status.className}`}>
                          <span className="status-dot" />
                          {status.label}
                        </span>
                      </div>

                      {/* รายละเอียด: วันที่และเวลา */}
                      <div className="booking-details">
                        <div className="booking-detail">
                          <span className="detail-icon" aria-hidden="true">▦</span>
                          <div>
                            <span className="detail-label">Date</span>
                            <strong>{formatDate(bookingDate)}</strong>
                          </div>
                        </div>

                        <div className="booking-detail">
                          <span className="detail-icon" aria-hidden="true">◷</span>
                          <div>
                            <span className="detail-label">Time</span>
                            <strong>
                              {formatTime(booking.start_time)} – {formatTime(booking.end_time)}
                            </strong>
                          </div>
                        </div>
                      </div>
                    </div>

                    {/* ส่วนปุ่มดำเนินการของการ์ด */}
                    <div className="booking-card-actions">
                      {/* ปุ่มเช็กอิน (ปิดการใช้งานเมื่อกำลังเช็กอิน / เช็กอินแล้ว / ไม่มีสิทธิ์) */}
                      {canCancel && (
                        <button
                          type="button"
                          className="checkin-button"
                          onClick={() => handleCheckIn(booking)}
                          disabled={
                            checkingInId === getBookingId(booking) ||
                            checkedIn ||
                            isIneligible
                          }
                        >
                          {checkingInId === getBookingId(booking)
                            ? "Checking in..."
                            : checkedIn
                              ? "✓ Checked in"
                              : "Check-in"}
                        </button>
                      )}

                      {/* ปุ่มยกเลิกการจอง */}
                      {canCancel && (
                        <button
                          type="button"
                          className="cancel-booking-button"
                          disabled={cancellingId === getBookingId(booking)}
                          onClick={() => handleCancel(booking)}
                        >
                          {cancellingId === getBookingId(booking)
                            ? "Cancelling..."
                            : "Cancel booking"}
                        </button>
                      )}

                      {/* ข้อความบอกสถานะท้ายการ์ด */}
                      <span className="booking-footer-note">
                        {status.className === "cancelled"
                          ? "This reservation has been cancelled."
                          : status.className === "completed"
                            ? "This reservation is complete."
                            : checkedIn
                              ? "You have checked in."
                              : "Please check in at the venue."}
                      </span>
                    </div>
                  </article>
                );
              })}
            </div>
          )}
        </section>

        {/* ส่วนท้ายหน้า */}
        <footer className="mybooking-footer">
          <p>ROOM RESERVE</p>
          <span>Make room for what matters.</span>
        </footer>
      </main>
    </div>
  );
}

export default Mybooking;
